<script setup lang="ts">
import { computed } from 'vue'
const props=withDefaults(defineProps<{labels:string[]; values:number[]; unit?:string; bars?:boolean; series?:{name:string;color:string;values:number[]}[]}>(),{unit:'',bars:false})
const max=computed(()=>Math.max(1,...props.values,...(props.series||[]).flatMap(s=>s.values))),x=(i:number)=>55+(i+.5)*520/Math.max(1,props.labels.length),y=(v:number)=>180-v/max.value*145
const line=computed(()=>props.values.map((v,i)=>`${x(i)},${y(v)}`).join(' '))
</script>
<template><svg class="fit-chart" viewBox="0 0 620 225" role="img" :aria-label="'历史趋势，单位'+unit"><g v-for="i in [0,1,2,3,4]" :key="i"><line x1="45" x2="595" :y1="180-i*36.25" :y2="180-i*36.25" stroke="var(--line)"/><text x="35" :y="184-i*36.25" text-anchor="end">{{ (max*i/4).toFixed(max>10?0:1) }}</text></g><text x="15" y="20">{{ unit }}</text><template v-if="series"><g v-for="(s,j) in series" :key="s.name"><rect v-for="(v,i) in s.values" :key="i" :x="x(i)-25+j*17" :y="y(v)" width="14" :height="180-y(v)" rx="4" :fill="s.color"><title>{{ labels[i] }} · {{ s.name }} {{ v }}{{ unit }}</title></rect></g></template><template v-else-if="bars"><rect v-for="(v,i) in values" :key="i" :x="x(i)-12" :y="y(v)" width="24" :height="180-y(v)" rx="5" fill="#53bc99"><title>{{ labels[i] }} · {{ v }}{{ unit }}</title></rect></template><template v-else-if="values.length"><polygon :points="`${x(0)},180 ${line} ${x(values.length-1)},180`" fill="#42bc9620"/><polyline :points="line" fill="none" stroke="#219e77" stroke-width="3"/><g v-for="(v,i) in values" :key="i"><circle :cx="x(i)" :cy="y(v)" r="5" fill="#199d77"/><text :x="x(i)" :y="y(v)-12" text-anchor="middle">{{ Number(v.toFixed(1)) }}</text><title>{{ labels[i] }} · {{ v }}{{ unit }}</title></g></template><text v-for="(label,i) in labels" :key="i" :x="x(i)" y="210" text-anchor="middle">{{ label }}</text><text v-if="!values.length&&!series" x="310" y="100" text-anchor="middle">暂无记录，补录后将在这里显示趋势</text></svg></template>
